int fd = open("file.txt", O_RDONLY);
if (fork() == 0) {                 /* 자식 */
    lseek(fd, 10, SEEK_SET);
    return 0;
}
wait(NULL);                        /* 부모 */
printf("%ld\n", (long)lseek(fd, 0, SEEK_CUR));   /* 10: 열린 파일 항목을 공유 */

unsigned long long max_file_size(unsigned long long B) {
    unsigned long long p = B / 4;                   /* 블록당 포인터 수 */
    unsigned long long blocks = 12 + p + p*p + p*p*p;
    return blocks * B;
}
/* max_file_size(4096) == 4402345721856  (약 4.004 TiB)
   max_file_size(1024) == 17247252480    (약 16.06 GiB) */
